insert into projects ("slug", "order", "title", "summary", "description", "objective", "results", "area", "status", "period", "image", "tech", "team", "repo") values
  ('careon', 1, '{"pt":"CareOn"}'::jsonb, '{"pt":"Aplicativo de gestão de saúde rotineira: remédios, compromissos de saúde e consulta de preços.","en":"An app for managing everyday health: medicines, health appointments and price lookups.","es":"Aplicación para gestionar la salud del día a día: medicamentos, citas médicas y consulta de precios."}'::jsonb, '{"pt":"O CareOn é um aplicativo para organizar a saúde no dia a dia. Nele dá para cadastrar remédios e compromissos de saúde, como exames e cirurgias, marcar os remédios já tomados e pesquisar o preço de remédios na Drogasil.\n\nOs preços vêm do site da farmácia e podem variar.","en":"CareOn is an app for keeping your health organized day to day. You can register medicines and health appointments, such as tests and surgeries, mark the medicines you''ve already taken and look up medicine prices at Drogasil.\n\nPrices come from the pharmacy''s website and may vary.","es":"CareOn es una aplicación para organizar la salud en el día a día. Permite registrar medicamentos y citas médicas, como exámenes y cirugías, marcar los medicamentos ya tomados y consultar el precio de medicamentos en Drogasil.\n\nLos precios vienen del sitio web de la farmacia y pueden variar."}'::jsonb, '{"pt":"Construir uma aplicação funcional de gestão de saúde rotineira, com app mobile em React Native e Expo, API em Django, banco PostgreSQL no Supabase e web scraping para consultar os preços.","en":"To build a working app for managing everyday health, with a mobile app in React Native and Expo, an API in Django, a PostgreSQL database on Supabase and web scraping to look up prices.","es":"Construir una aplicación funcional para la gestión de la salud cotidiana, con una app móvil en React Native y Expo, una API en Django, una base de datos PostgreSQL en Supabase y web scraping para consultar los precios."}'::jsonb, '{"pt":"O resultado é um aplicativo Android, com build gerado pelo Expo.\n\nPedro Bizzari liderou a equipe e fez o app mobile, além de integrar o front-end com a API. Liam Vedovato Lopes desenvolveu o back-end em Django. João Victor Pereira Bicalho cuidou do banco no Supabase e do web scraping.\n\nNo front-end, o grupo praticou organização de telas, autenticação por token e validação de dados. No back-end, APIs REST, web scraping e deploy.","en":"The result is an Android app, built with Expo.\n\nPedro Bizzari led the team and built the mobile app, as well as integrating the front end with the API. Liam Vedovato Lopes developed the Django back end. João Victor Pereira Bicalho took care of the Supabase database and the web scraping.\n\nOn the front end, the group practiced screen organization, token authentication and data validation. On the back end, REST APIs, web scraping and deployment.","es":"El resultado es una aplicación para Android, generada con Expo.\n\nPedro Bizzari lideró el equipo y desarrolló la app móvil, además de integrar el front-end con la API. Liam Vedovato Lopes desarrolló el back-end en Django. João Victor Pereira Bicalho se encargó de la base de datos en Supabase y del web scraping.\n\nEn el front-end, el grupo practicó la organización de pantallas, la autenticación por token y la validación de datos. En el back-end, APIs REST, web scraping y despliegue."}'::jsonb, 'Engenharia de Software', 'concluido', '2026.1', null, array['React Native', 'Expo', 'TypeScript', 'Python', 'Django', 'PostgreSQL'], array['Pedro Bizzari', 'Liam Vedovato Lopes', 'João Vitor P Bicalho'], 'https://github.com/PedroBZR12/careon'),
  ('mapa-do-campus', 1, '{"pt":"Mapa do Campus","en":"Campus Map","es":"Mapa del Campus"}'::jsonb, '{"pt":"Mapa 3D do campus Campus Consolação - Marquês de Paranaguá, feito em React","en":"A 3D map of the Consolação - Marquês de Paranaguá campus, built in React","es":"Mapa 3D del Campus Consolação - Marquês de Paranaguá, hecho en React"}'::jsonb, '{"pt":"https://mapa.puctech.com.br/pt"}'::jsonb, null, null, 'Engenharia de Software', 'em-andamento', '2026.2', '/projetos/mapa-do-campus.png', array['React', 'Typescript', 'Next.js', 'React Three Fiber'], array['Raul Kolaric'], 'https://github.com/PUCTech/3D-puc'),
  ('minerva', 2, '{"pt":"Minerva"}'::jsonb, '{"pt":"Aplicativo para organizar a vida acadêmica: disciplinas, notas, faltas, tarefas e arquivos.","en":"An app for organizing academic life: courses, grades, absences, assignments and files.","es":"Aplicación para organizar la vida académica: materias, notas, faltas, tareas y archivos."}'::jsonb, '{"pt":"O Minerva é um aplicativo para o estudante universitário reunir a vida acadêmica em um lugar só: disciplinas, notas, faltas, tarefas e arquivos. A ideia veio de um problema comum na faculdade, a dificuldade de planejar o tempo.\n\nFoi feito no First Steps, programa da PUC Tech, pensando na rotina do universitário brasileiro.","en":"Minerva is an app that lets university students keep their academic life in one place: courses, grades, absences, assignments and files. The idea came from a common problem in college: how hard it is to plan your time.\n\nIt was built during First Steps, a PUC Tech program, with the routine of Brazilian university students in mind.","es":"Minerva es una aplicación para que el estudiante universitario reúna su vida académica en un solo lugar: materias, notas, faltas, tareas y archivos. La idea surgió de un problema común en la universidad: la dificultad de planificar el tiempo.\n\nSe desarrolló en First Steps, un programa de PUC Tech, pensando en la rutina del universitario brasileño."}'::jsonb, '{"pt":"Cada disciplina é cadastrada com créditos, carga horária e a média necessária. As notas entram com pesos e a média é calculada na hora. As faltas são registradas e o app mostra quantas ainda restam até o limite, calculado pela carga horária.\n\nHá também um calendário para tarefas, provas e prazos, e uma seção para arquivos.","en":"Each course is registered with its credits, workload and required average. Grades are entered with weights and the average is calculated on the spot. Absences are tracked and the app shows how many are left before the limit, calculated from the workload.\n\nThere''s also a calendar for assignments, exams and deadlines, and a section for files.","es":"Cada materia se registra con sus créditos, carga horaria y la nota media necesaria. Las notas se ingresan con pesos y el promedio se calcula al instante. Las faltas quedan registradas y la app muestra cuántas quedan antes del límite, calculado según la carga horaria.\n\nTambién hay un calendario para tareas, exámenes y plazos, y una sección para archivos."}'::jsonb, '{"pt":"O app está publicado na nuvem, com back-end em Spring, interface em Streamlit e autenticação por JWT.","en":"The app is deployed in the cloud, with a Spring back end, a Streamlit interface and JWT authentication.","es":"La app está publicada en la nube, con back-end en Spring, interfaz en Streamlit y autenticación con JWT."}'::jsonb, 'Engenharia de Software', 'concluido', null, '/projetos/minerva.png', array['Java', 'Spring', 'Python', 'Streamlit', 'PostgreSQL', 'H2', 'JWT', 'Docker'], array['Kauã Bezerra', 'Luís Augusto', 'Túlio Gonçalves Vieira'], 'https://github.com/Luis-coelho30/minerva-app'),
  ('rothernet', 3, '{"pt":"Rothernet"}'::jsonb, '{"pt":"Restaurante virtual com agente de IA que atende o cliente por voz, em português.","en":"A virtual restaurant with an AI agent that serves customers by voice, in Portuguese.","es":"Restaurante virtual con un agente de IA que atiende al cliente por voz, en portugués."}'::jsonb, '{"pt":"O Rothernet é um restaurante virtual com atendimento por voz. O cliente conversa com um assistente de IA, que entende o pedido, responde dúvidas e devolve a resposta em áudio, em português.","en":"Rothernet is a virtual restaurant with voice service. The customer talks to an AI assistant that understands the order, answers questions and replies with audio, in Portuguese.","es":"Rothernet es un restaurante virtual con atención por voz. El cliente conversa con un asistente de IA que entiende el pedido, responde dudas y devuelve la respuesta en audio, en portugués."}'::jsonb, '{"pt":"O cliente grava um áudio no front-end feito em Unity. O Whisper transcreve a fala e o sistema captura os dados do cliente e do pedido.\n\nA IA responde com base em documentos que descrevem o cardápio e as regras do restaurante (técnica de RAG, com LangChain, ChromaDB e um modelo da OpenAI). A resposta vira áudio por síntese de voz e volta pelo back-end em FastAPI, via WebSockets.\n\nCada cliente tem um User ID, que dá acesso ao histórico de conversa e de pedidos, guardados no banco com SQLAlchemy.","en":"The customer records audio in the Unity front end. Whisper transcribes the speech and the system captures the customer''s details and the order.\n\nThe AI answers based on documents describing the restaurant''s menu and rules (a RAG technique, with LangChain, ChromaDB and an OpenAI model). The answer is turned into audio with speech synthesis and sent back through the FastAPI back end, over WebSockets.\n\nEach customer has a User ID that gives access to their conversation and order history, stored in the database with SQLAlchemy.","es":"El cliente graba un audio en el front-end hecho en Unity. Whisper transcribe el habla y el sistema captura los datos del cliente y del pedido.\n\nLa IA responde a partir de documentos que describen el menú y las reglas del restaurante (técnica de RAG, con LangChain, ChromaDB y un modelo de OpenAI). La respuesta se convierte en audio mediante síntesis de voz y vuelve por el back-end en FastAPI, vía WebSockets.\n\nCada cliente tiene un User ID que da acceso al historial de conversaciones y pedidos, guardados en la base de datos con SQLAlchemy."}'::jsonb, '{"pt":"O projeto roda em nuvem, no Railway.","en":"The project runs in the cloud, on Railway.","es":"El proyecto funciona en la nube, en Railway."}'::jsonb, 'Inteligência Artificial', 'concluido', null, null, array['Unity', 'Python', 'FastAPI', 'WebSockets', 'LangChain', 'ChromaDB', 'Whisper', 'SQLAlchemy', 'PostgreSQL'], array['Guilherme Schnekenberg', 'Grazielle Batista de Almeida', 'Nícolas Okamoto Celestrino', 'Cesar Silva'], 'https://github.com/schnekenberg/puctech_rothernet');
